const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),external=(url,label)=>/^https?:\/\//.test(url||'')?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:'';
const categories={career:'職歴・学歴・議員歴',community:'PTA・地域活動',organization:'団体・役職',party:'政党・政策団体',policy:'政策・公約',activity:'議会・公的活動'};
let rows=[],coverage={municipalities:{},meta:{totals:{}}},page=1,active=null,region=null,regionQuery='',regionTab='council',chosen=new Set(),requestId=0;const cache=new Map(),pageSize=24,isBunkyo=m=>m.code==='13105',info=m=>coverage.municipalities[m.code]||{},detailed=m=>!!info(m).people;
try{const results=await Promise.all([fetch('data/national.json'),fetch('data/coverage.json')]);if(results.some(r=>!r.ok))throw Error('自治体データを取得できませんでした');const [d,c]=await Promise.all(results.map(r=>r.json()));rows=d.municipalities;coverage=c;const t=c.meta.totals;$('#stats').innerHTML=[[rows.length.toLocaleString(),'自治体','全国の市区町村'],[c.meta.municipalities.toLocaleString(),'自治体に人物情報',`${c.meta.prefectures}都道府県から収録`],[t.people.toLocaleString(),'人物レコード','名簿・プロフィール・予定者'],[t.findings.toLocaleString(),'調査記録','経歴・団体・政策など']].map(([n,u,t])=>`<div class="stat"><b>${n}</b>${u}<small>${t}</small></div>`).join('');$('#pref').innerHTML+=[...new Set(rows.map(x=>x.pref))].map(p=>`<option>${esc(p)}</option>`).join('');$('#coverage-summary').textContent=`議員等 ${t.council.toLocaleString()}人 ／ 次回選挙の発表等 ${t.candidates.toLocaleString()}人 ／ 経歴・議員歴の記録がある人物 ${t.careerProfiles.toLocaleString()}人。取得・調査日 ${c.meta.collectedAt}。`;const code=new URLSearchParams(location.search).get('municipality');if(code){const m=rows.find(x=>x.code===code);if(m){$('#pref').value=m.pref;show(m)}}render()}catch(e){$('#results').innerHTML=`<div class="empty">${esc(e.message)}<br>時間をおいて再読み込みしてください。</div>`}
function filtered(){const q=$('#search').value.trim().replace(/\s/g,''),pref=$('#pref').value,c=$('#coverage').value;return rows.filter(m=>(!pref||m.pref===pref)&&(!q||[m.pref,m.name,m.mayor?.name,info(m).names].join('').replace(/\s/g,'').includes(q))&&(!c||(c==='detailed'?detailed(m):c==='candidates'?info(m).candidates:c==='careers'?info(m).careerProfiles:!!m.mayor?.name)))}
function render(){const result=filtered(),pages=Math.max(1,Math.ceil(result.length/pageSize));page=Math.min(page,pages);$('#resultmeta').textContent=`${result.length.toLocaleString()}自治体 ／ ${page}・${pages}ページ`;$('#results').innerHTML=result.slice((page-1)*pageSize,page*pageSize).map(m=>{const c=info(m);return `<article class="card"><div class="cardhead"><span>${esc(m.pref)} · ${m.code}</span><span class="badge">${detailed(m)?c.people+'人を収録':'首長名簿'}</span></div><h3>${esc(m.name)}</h3><div class="mayor"><small>首長名簿</small><div>${esc(m.mayor?.name||'氏名未確認')}<div class="date">${esc(m.mayor?.asOf||'不明')}現在の資料</div></div></div><div class="coverage-line">${c.council?'議員等 '+c.council+'人':''} ${c.candidates?'・予定者の発表等 '+c.candidates+'人':''} ${c.careerProfiles?'・経歴 '+c.careerProfiles+'人':''}</div><div class="cardfooter"><span>${detailed(m)?'収録は一部・根拠と時点を表示':'人物の詳細は未収録'}</span><button class="btn" data-code="${m.code}">台帳を開く →</button></div></article>`}).join('')||'<div class="empty">条件に合う自治体が見つかりません。</div>';$('#pager').innerHTML=`<button class="btn" data-page="${page-1}" ${page===1?'disabled':''}>← 前へ</button><span>${page} / ${pages}</span><button class="btn" data-page="${page+1}" ${page===pages?'disabled':''}>次へ →</button>`}
function issueLink(m,name=''){return 'https://github.com/nobby11334/Localpoliticians/issues/new?title='+encodeURIComponent(m.pref+m.name+' '+name+'の情報追加・訂正')+'&body='+encodeURIComponent('自治体コード: '+m.code+'\n対象の人物: '+name+'\n出典URL:\n資料基準日:\n追加・訂正内容:\n')}
async function show(m){active=m;regionQuery='';regionTab='council';chosen.clear();const id=++requestId;$('#detailbody').innerHTML='<p>出典付きの人物情報を読み込んでいます…</p>';if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0;const u=new URL(location.href);u.searchParams.set('municipality',m.code);history.replaceState(null,'',u);try{if(cache.has(m.code))region=cache.get(m.code);else if(detailed(m)){const r=await fetch(`data/regions/${m.code}.json`);if(!r.ok)throw Error('人物データを取得できませんでした');const v=await r.json();if(id!==requestId)return;cache.set(m.code,v);region=v}else region={people:[],counts:{}};if(id!==requestId)return;renderRegion()}catch(e){if(id===requestId)$('#detailbody').innerHTML=`<p>${esc(e.message)}</p><button class="btn" data-code="${m.code}">再読み込み</button>`}}
const sourcesHtml=p=>(p.sources||[]).map(s=>`<div class="evidence">${external(s.url,s.title||'掲載資料')}<small>${esc(s.kind||'')} ／ 資料時点 ${esc(s.asOf||'掲載日時不明')}</small></div>`).join('');
function candidacy(p){const c=p.candidate;if(!c)return '<p class="muted">次回選挙への出馬表明等は未確認。不出馬を意味しません。</p>';return `<div class="candidacy"><span class="badge">${esc(c.status)}</span><h3>${esc(c.target||'次回選挙')}</h3><p>${esc(c.note||'届出前の発表情報。正式な立候補届出とは区別します。')}</p><small>発表・掲載日 ${esc(c.announcedAt||'不明')}</small>${(c.sources||[]).map(s=>`<div>${external(s.url,s.title||'発表資料')} <small>${esc(s.date||'')}</small></div>`).join('')}</div>`}
function renderRegion(){const m=active,mayor=m.mayor,ps=region.people;$('#detailbody').innerHTML=`<div class="eyebrow">${esc(m.pref)} / CIVIC RECORDS</div><h1>${esc(m.name)}</h1><div class="region-summary">人物 ${ps.length}人 ／ 調査記録 ${info(m).findings||0}件</div><div class="notice">名簿は資料掲載時点の記録です。議会の全員名簿と政党の所属名簿を区別します。未掲載は不在・不出馬を意味しません。政党別の人数比較には使えません。同じ人物が名簿表記の違いで別掲載になる場合があります。</div><div class="links">${external(m.officialURL,'自治体公式サイト')}<a href="${esc(issueLink(m))}">追加・訂正を提案 ↗</a>${isBunkyo(m)?'<a class="btn primary" href="bunkyo.html">文京区の詳しい比較台帳 →</a>':''}</div><h2>首長</h2><div class="leader"><span class="badge">全国名簿・資料時点の在職者</span><strong>${esc(mayor?.name||'氏名未確認')}</strong><small>資料基準日 ${esc(mayor?.asOf||'不明')} ／ 現在の在職は未確認</small><div>${external(mayor?.sourceURL,'全国名簿の出典')}</div></div>${ps.filter(p=>p.role==='mayor').map(p=>personCard(p)).join('')}<div class="region-tabs">${[['council','議員・経歴',ps.filter(p=>p.role!=='mayor').length],['candidates','次回選挙の発表等',ps.filter(p=>p.candidate).length],['careers','職歴・地域活動',ps.filter(p=>p.findings.some(f=>['career','community','organization'].includes(f.category))).length]].map(([k,t,n])=>`<button class="btn ${regionTab===k?'primary':''}" data-region-tab="${k}">${t} ${n}</button>`).join('')}</div><label class="region-search">人物・所属・経歴を検索<input id="region-search" type="search" value="${esc(regionQuery)}" placeholder="氏名、PTA、職歴、政党、団体名など"></label><div id="region-list"></div><div id="region-compare"></div><p class="muted">${ps.length?'収録は出典を確認できた範囲に限ります。全議員・全経歴・全予定者の網羅を保証しません。':'議員・経歴・次回選挙の発表は未収録です。'}資料の変更検出と、人物情報の確認・反映は別の工程です。</p>`;$('#region-search').oninput=e=>{regionQuery=e.target.value;renderRegionList()};renderRegionList()}
function personCard(p){return `<article class="person-entry"><div><span class="badge">${esc(p.currentLabel||(p.role==='candidate'?'選挙の予定者資料':p.office)||'議員等')}</span>${p.candidate?' <span class="badge">'+esc(p.candidate.status)+'</span>':''}<h3><button class="person-button" data-person="${p.id}">${esc(p.name)} →</button></h3><div class="muted">${esc(p.party||'党籍未確認')}${p.group?' ／ 会派 '+esc(p.group):''}</div><div class="date">${esc(p.rosterKind||p.sources?.[0]?.kind||'掲載資料')} ／ ${esc(p.asOf||'掲載日時不明')}</div>${p.findings.length?'<p class="snippet">'+esc(p.findings.find(f=>f.category==='career')?.title||p.findings[0].title)+'</p>':''}</div><div class="person-actions"><span class="date">${p.findings.length}件の記録</span><label><input type="checkbox" data-choose="${p.id}" ${chosen.has(p.id)?'checked':''}> 比較</label></div></article>`}
function renderRegionList(){const q=regionQuery.replace(/\s/g,''),ps=region.people.filter(p=>(regionTab==='candidates'?p.candidate:regionTab==='careers'?p.findings.some(f=>['career','community','organization'].includes(f.category)):p.role!=='mayor')&&(!q||[p.name,p.party,p.group,...p.findings.map(f=>f.title+' '+f.summary)].join('').replace(/\s/g,'').includes(q)));$('#region-list').innerHTML=`<div class="muted">${ps.length}人を表示 ／ 人物は氏名順・収録は一部</div>`+ps.map(personCard).join('')+(ps.length?'':'<div class="empty">この条件の人物情報は未収録です。</div>');renderCompareBar()}
function renderCompareBar(){if($('#region-compare'))$('#region-compare').innerHTML=chosen.size?`<button class="btn primary" id="compare-people">選択した${chosen.size}人を比較 →</button>`:''}
function fact(f){return `<article class="research-fact"><div><span class="badge">${esc(categories[f.category]||f.category)}</span> <span class="date">${esc(f.sourceType||'出典参照')}</span></div><h3>${esc(f.title)}</h3><p>${esc(f.summary||'')}</p><small>期間 ${esc(f.period||'不明')} ／ 資料時点 ${esc(f.asOf||'掲載日時不明')}</small><div class="links">${external(f.url,f.source||'出典を確認')}</div></article>`}
function showPerson(id){const p=region.people.find(p=>p.id===id);if(!p)return;$('#detailbody').innerHTML=`<button class="btn" id="back-region">← ${esc(active.name)}の人物一覧</button><h1>${esc(p.name)}</h1><span class="badge">${esc(p.currentLabel||(p.role==='candidate'?'選挙の予定者資料':p.office)||'掲載人物')}</span>${p.sourceNames?.length>1?'<p class="date">出典の氏名表記：'+p.sourceNames.map(esc).join(' ／ ')+'</p>':''}<p>${esc(p.party||'党籍未確認')}${p.group?' ／ 会派 '+esc(p.group):''}</p><div class="muted">資料時点 ${esc(p.asOf||'掲載日時不明')} ／ 取得・調査 ${esc(p.collectedAt||coverage.meta.collectedAt)}</div><div class="links">${external(p.website?.url,p.website?.kind||'掲載プロフィール')}<a href="${esc(issueLink(active,p.name))}">追加・訂正を提案 ↗</a></div>${candidacy(p)}<h2>名簿・プロフィールの根拠</h2>${sourcesHtml(p)}<h2 style="margin-top:28px">経歴・団体・活動の記録 <span class="badge">${p.findings.length}件</span></h2>${Object.entries(categories).map(([k,v])=>{const fs=p.findings.filter(f=>f.category===k);return `<section class="fact-section"><h3>${v}</h3>${fs.length?fs.map(fact).join(''):'<p class="muted">この分類の記録は未収録です。</p>'}</section>`}).join('')}<div class="notice">${esc(p.researchNotes||'名簿への掲載や本人・政党のプロフィールを、掲載範囲で記録しています。役職の実態・報酬・政策成果や功績の帰属を自動では認定していません。')}</div>`;$('#detail').scrollTop=0}
function comparePeople(){const ps=region.people.filter(p=>chosen.has(p.id));$('#detailbody').innerHTML=`<button class="btn" id="back-region">← 人物一覧</button><h1>出典から見比べる</h1><div class="compare-scroll"><table><thead><tr><th>項目</th>${ps.map(p=>`<th>${esc(p.name)}</th>`).join('')}</tr></thead><tbody><tr><th>掲載区分・所属</th>${ps.map(p=>`<td>${esc(p.office)}<br>${esc(p.party||'未確認')}<br><small>${esc(p.asOf||'資料日不明')}</small>${sourcesHtml(p)}</td>`).join('')}</tr><tr><th>次回選挙</th>${ps.map(p=>`<td>${candidacy(p)}</td>`).join('')}</tr>${Object.entries(categories).map(([k,v])=>`<tr><th>${v}</th>${ps.map(p=>`<td>${p.findings.filter(f=>f.category===k).map(fact).join('')||'未収録'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="muted">情報量の差は調査範囲の差を含み、活動量や人物の優劣を示しません。</p>`;$('#detail').scrollTop=0}
for(const selector of ['#pref','#search','#coverage'])$(selector).addEventListener(selector==='#search'?'input':'change',()=>{page=1;render()});document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.code)show(rows.find(m=>m.code===b.dataset.code));if(b.dataset.page){page=Number(b.dataset.page);render();$('.finder').scrollIntoView({block:'start'})}if(b.dataset.regionTab){regionTab=b.dataset.regionTab;renderRegion()}if(b.dataset.person)showPerson(b.dataset.person);if(b.id==='back-region')renderRegion();if(b.id==='compare-people')comparePeople()});document.addEventListener('change',e=>{if(!e.target.dataset.choose)return;const id=e.target.dataset.choose;if(e.target.checked){if(chosen.size>=4){e.target.checked=false;return}chosen.add(id)}else chosen.delete(id);renderCompareBar()});function closeDetail(){$('#detail').close();requestId++;const u=new URL(location.href);u.searchParams.delete('municipality');history.replaceState(null,'',u)}$('#close').onclick=closeDetail;$('#detail').addEventListener('cancel',()=>{requestId++;const u=new URL(location.href);u.searchParams.delete('municipality');history.replaceState(null,'',u)});
